challenge.verificationSource:
mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("matrix=[[0,10,15,20],[10,0,35,25],[15,35,0,30],[20,25,30,0]]","80"),
        ("matrix=[[0,1,10],[1,0,2],[10,2,0]]","13"),
        ("matrix=[[0,5],[5,0]]","10"),
        ("matrix=[[0,1,5],[1,0,2],[5,2,0]]","8"),
        ("matrix=[[0,3,4],[3,0,1],[4,1,0]]","8"),
        ("  \nmatrix=[[0,10,15,20],[10,0,35,25],[15,35,0,30],[20,25,30,0]]\n  ","80"),
        ("\nmatrix=[[0,3,4],[3,0,1],[4,1,0]]\n","8")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS bitmask-dp");
}
